import{z as i,x as s,o as B,c as d,q as A,j as n,D as e,d as r,s as l,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"人力资本：一般与特殊训练","description":"","frontmatter":{"title":"人力资本：一般与特殊训练","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/human-capital-becker.md","filePath":"econ/human-capital-becker.md","lastUpdated":1791063341000}'),p={name:"econ/human-capital-becker.md"};function h(c,a,m,C,u,D){const t=s("Mermaid");return B(),d("div",null,[a[2]||(a[2]=A('<h1 id="人力资本-一般与特殊训练" tabindex="-1">人力资本：一般与特殊训练 <a class="header-anchor" href="#人力资本-一般与特殊训练" aria-label="Permalink to &quot;人力资本：一般与特殊训练&quot;">​</a></h1><div class="epigraph"><p>训练若带来一般技能，市场会把学费记在受训期的工资单上；若是特殊技能，雇主必须分摊——否则留不住人。</p><footer>—— 据 Becker, Human Capital, 1964；Ben-Porath, The Production of Human Capital and the Life Cycle of Earnings, JPE, 1967 整理</footer></div><p><a href="/econ/compensating-differentials">上一课</a>把工资差的属性维度钉完：风险、脏活、偏远由享乐工资函数定价。但工资剖面最粗的形态还没解释：为什么工资随年龄先陡后平、教育年限高的人整个剖面往上抬？缺口是把「能力」当成可投资的存量——人力资本。本课讲 Becker 的一般与特殊训练之分、成本谁付、年龄-收入剖面怎么读。教育到底是真技能还是标签，本单元后面的信号课再对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课的属性是岗位给定的特征；本课的变量长在人身上。投资教育或培训，当期少赚（学费、受训期低工资），未来多赚。缺口有三个：投资谁定、成本谁付、剖面为什么凹。不分投资类型，「企业送员工去培训」会被当成反竞争模型的反例，其实它是模型自己的推论——分界在技能带走之后还值不值钱。</p><h3 id="一般与特殊的分界" tabindex="-1">一般与特殊的分界 <a class="header-anchor" href="#一般与特殊的分界" aria-label="Permalink to &quot;一般与特殊的分界&quot;">​</a></h3><p>一般技能换个雇主同样值钱；特殊技能只在本企业提高边际产出，带走归零。这条分界决定付费结构，是 Becker 1964 的核心命题。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>竞争市场基准下推付费结构。一般训练：若企业垫付学费，训练完成后市场工资追平工人（已抬高的一般）生产率，工人可以跳槽，垫付收不回。所以一般训练由工人付费：受训期工资被压到低于当期边际产出，差额即学费。特殊训练：技能带走归零，跳槽对双方都是损失，租金必须分享——培训期工资高于工人的外部选择（否则他不学），训练后工资低于其含特殊技能的边际产出、高于外部工资；成本与收益分摊，流动率随之下降。专用投资的这套治理，在<a href="/econ/hold-up-gh">套牢与专用性</a>的口径里已经搭过台。</p><p><span class="marginnote">数字实例：一般培训期，工人当期边际产出 5000 元，市场工资也值 5000 元，但企业只发 3500 元——扣下的 1500 元就是这期培训的「学费」。结业后他跳槽也能拿到 5000 元以上，所以垫付的只能是自己的低工资，企业一分不能多掏。</span></p><p><span class="marginnote">直觉类比：特殊技能像只在这一家餐厅有用的秘方。老板不敢让你白学（怕你端着秘方走），你也不敢自己全垫（怕学成后被压价），于是学费一起摊：受训期你拿中间水平的工资，结业后拿介于外部工资与含秘方产出之间的钱——走人亏、留下赚，双方都被拴住。</span></p><p>年龄-收入剖面：Ben-Porath 1967 把人力资本写成存量上的生产——投资先回报自身（复合增长），且剩余工作年限越长、投资的租期越长，于是年轻时投资密、随年龄递减；产出随存量上升、投资随年龄下降，剖面先陡后平，凹形。教育年限把整个剖面上移：Mincer 1974 的对数工资回归</p> \\[\\ln w = \\alpha + \\rho\\, s + \\beta_1 x + \\beta_2 x^2 + \\cdots \\]<p>把教育年限 \\(s\\) 与经验 \\(x\\) 的回报分开，\\(\\rho\\) 的估计多落在每年 6%–12%（Heckman 等 2006 的综述与再检验）。</p>',14)),(B(),n(o,null,{default:e(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%2225%20%E5%B2%81%EF%BC%9A%E5%89%A9%E4%BD%99%E7%A7%9F%E6%9C%9F%E7%BA%A6%2040%20%E5%B9%B4%22%5D%20--%3E%20I1%5B%22%E6%8A%95%E8%B5%84%E5%AF%86%E9%9B%86%EF%BC%9A%E5%AD%A6%E5%BE%97%E5%A4%9A%22%5D%0A%20%20B%5B%2245%20%E5%B2%81%EF%BC%9A%E7%A7%9F%E6%9C%9F%E7%BA%A6%2020%20%E5%B9%B4%22%5D%20--%3E%20I2%5B%22%E6%8A%95%E8%B5%84%E6%94%BE%E7%BC%93%EF%BC%9A%E5%B0%91%E9%87%8F%E8%A1%A5%E8%AF%BE%22%5D%0A%20%20C%5B%2260%20%E5%B2%81%EF%BC%9A%E7%A7%9F%E6%9C%9F%E5%8F%AA%E5%89%A9%E5%87%A0%E5%B9%B4%22%5D%20--%3E%20I3%5B%22%E5%87%A0%E4%B9%8E%E4%B8%8D%E6%8A%95%EF%BC%9A%E5%8F%AA%E5%90%83%E5%AD%98%E9%87%8F%22%5D%0A%20%20I1%20--%3E%20W%5B%22%E5%B7%A5%E8%B5%84%E5%BF%AB%E9%80%9F%E4%B8%8A%E5%8D%87%22%5D%0A%20%20I2%20--%3E%20W%0A%20%20I3%20--%3E%20FLAT%5B%22%E5%B7%A5%E8%B5%84%E8%B5%B0%E5%B9%B3%EF%BC%9A%E5%89%96%E9%9D%A2%E5%91%88%E5%87%B9%E5%BD%A2%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：Mincer 方程就是把工资差拆成三块——教育年限 \\(s\\)（每多读一年涨约 \\(\\rho\\)）、经验 \\(x\\)（早期涨得快）、经验的平方 \\(x^2\\)（后期放缓）。它默认是相关而非因果：能力偏误要靠工具变量另外压。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"凹形不是偶然：投资前密后疏是租期效应——同样的技能，二十五岁学有四十年收租，五十五岁学只剩十年。一般与特殊的分界同时预测流动率：只受一般训练者到处值钱、流动率高；受特殊训练者外部工资低、流动率低，数据里培训与长任期相伴随。付费结构可检验：企业出钱的培训偏特殊技能（专有流程、内部系统），一般技能多由工人自费或由学校承担——分工在数据里对得上。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"「企业愿意免费提供通用培训」在竞争基准里是亏本买卖：垫付收不回。Acemoglu–Pischke 1999 指出工资压缩（买方垄断、制度、信息摩擦）会让企业也付一般训练——不是 Becker 错了，是竞争假设松了之后付费结构跟着变。")],-1)),(B(),n(o,null,{default:e(()=>[l(t,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E6%95%99%E8%82%B2%2F%E5%9F%B9%E8%AE%AD%E6%8A%95%E8%B5%84%22%5D%20--%3E%20GEN%5B%22%E4%B8%80%E8%88%AC%E6%8A%80%E8%83%BD%EF%BC%9A%E5%A4%84%E5%A4%84%E5%80%BC%E9%92%B1%22%5D%0A%20%20INV%20--%3E%20SPEC%5B%22%E7%89%B9%E6%AE%8A%E6%8A%80%E8%83%BD%EF%BC%9A%E6%9C%AC%E4%BC%81%E4%B8%9A%E5%80%BC%E9%92%B1%22%5D%0A%20%20GEN%20--%3E%20P1%5B%22%E5%B7%A5%E4%BA%BA%E4%BB%98%E8%B4%B9%EF%BC%9A%E5%8F%97%E8%AE%AD%E6%9C%9F%E5%B7%A5%E8%B5%84%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20SPEC%20--%3E%20P2%5B%22%E6%88%90%E6%9C%AC%E4%B8%8E%E7%A7%9F%E9%87%91%E5%88%86%E6%91%8A%EF%BC%9A%E6%B5%81%E5%8A%A8%E7%8E%87%E4%B8%8B%E9%99%8D%22%5D%0A%20%20P1%20--%3E%20PROF%5B%22%E5%B9%B4%E9%BE%84-%E6%94%B6%E5%85%A5%E5%89%96%E9%9D%A2%EF%BC%9A%E5%87%B9%E5%BD%A2%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20P2%20--%3E%20PROF%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课把教育全当生产率投资用；教育与工资正相关这个事实本身分不开技能与标签——文凭可能只是筛选装置，那个口径留给本单元后面的信号课。还有能力偏误：能力强的人教育多、工资也高，把能力误记在教育头上会高估 \\(\\rho\\)；用义务教育法、离最近大学的距离当工具变量往下降（Card 1999 的口径）。信贷约束决定谁能投资：教育的分布不只是偏好问题，也是融资问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一般训练工人付费（受训期低工资），特殊训练成本与租金双方分摊；分界是流动率。</li><li>年龄-收入剖面的凹形来自租期效应：投资随年龄递减（Ben-Porath 1967）。</li><li>教育年限的对数工资回报多估在每年 6%–12%，能力偏误用工具变量压。</li><li>教育是技能还是标签，本课未拆——留给信号课对照。</li><li>出处：Becker, Human Capital, 1964；Ben-Porath, JPE 1967；Mincer 1974；Acemoglu and Pischke 1999。</li></ul>',4))])}const P=i(p,[["render",h]]);export{f as __pageData,P as default};
